script:
(function () {
  'use strict';
  // Credit card minimum payment. Each month: interest = balance x APR / 12 is added to give the
  // statement balance S. The minimum due is the greater of the dollar floor and either
  //   p x S               ("percentage of the balance" method), or
  //   interest + p x S    ("interest plus a percentage" method),
  // rounded to the cent and capped at S (the last payment clears the card). No new charges.
  // The fixed-payment comparisons use the same monthly-rate simulation; the "pay off in N months"
  // payment is the level payment P = rB / (1 - (1 + r)^-n) rounded up to the cent (B / n at 0%).
  // Verified (scratchpad w2debt/cm.test.js):
  //   with the floor at $0 the balance after n months matches the closed forms
  //   B x ((1 + r)(1 - p))^n (percentage method) and B x (1 - p(1 + r))^n (interest-plus method);
  //   $5,000 at 22%, interest + 1%, $35 floor -> first minimum $142.59 (hand-checked: interest
  //   $91.67 + 1% of $5,091.67 = $50.92), paid off in 194 months with $7,548.41 total interest;
  //   $5,000 at 18% with a fixed $150 -> 47 months, the closed form n = -ln(1 - rB/P)/ln(1 + r) = 46.56;
  //   $5,000 at 22% in 36 months -> $190.96 a month (same value as the credit card payoff calculator);
  //   a 1.5% percentage-only minimum at 22% APR grows the balance and is reported as never paying off.
  var MAX_MONTHS = 1200;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function cents(x) { return Math.round(x * 100) / 100; }

  function minimumDue(statement, interest, method, pct, floor) {
    var due = method === 'interest' ? interest + pct * statement : pct * statement;
    due = Math.max(cents(due), floor);
    return Math.min(due, statement);
  }

  // Pays the minimum every month. Returns totals and a year-by-year summary.
  function simulateMinimum(balance, apr, method, pct, floor) {
    var r = apr / 12, bal = balance, totalInterest = 0, totalPaid = 0, years = [];
    var yr = null, first = 0;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var interest = cents(bal * r);
      var statement = bal + interest;
      var pay = minimumDue(statement, interest, method, pct, floor);
      if (m === 1) first = pay;
      if ((m - 1) % 12 === 0) { yr = { year: (m - 1) / 12 + 1, startMin: pay, paid: 0, interest: 0, balance: 0 }; years.push(yr); }
      bal = statement - pay;
      totalInterest += interest;
      totalPaid += pay;
      yr.paid += pay; yr.interest += interest; yr.balance = Math.max(bal, 0);
      if (bal <= 0.005) return { paidOff: true, months: m, interest: totalInterest, paid: totalPaid, first: first, years: years };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: totalInterest, paid: totalPaid, first: first, years: years };
  }

  function simulateFixed(balance, apr, payment) {
    var r = apr / 12, bal = balance, totalInterest = 0, totalPaid = 0;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var interest = cents(bal * r);
      bal += interest;
      var pay = Math.min(payment, bal);
      bal -= pay;
      totalInterest += interest;
      totalPaid += pay;
      if (bal <= 0.005) return { paidOff: true, months: m, interest: totalInterest, paid: totalPaid };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: totalInterest, paid: totalPaid };
  }

  function levelPayment(balance, apr, months) {
    var r = apr / 12;
    var p = r === 0 ? balance / months : r * balance / (1 - Math.pow(1 + r, -months));
    return Math.ceil(p * 100 - 1e-6) / 100;
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var cell = document.createElement('td');
      cell.textContent = text;
      tr.appendChild(cell);
    });
    body.appendChild(tr);
  }

  function clearResults() {
    ['cmFirst', 'cmTime', 'cmInterest', 'cmTotal'].forEach(function (id) { set(id, '–'); });
    set('cmTimeNote', '');
    clearBody('cmCompare');
    clearBody('cmSchedule');
  }

  function update() {
    var balance = num('cmBalance'), apr = num('cmRate'), pct = num('cmPercent'), floor = num('cmFloor'),
        method = document.getElementById('cmMethod').value, fixed = num('cmFixed'), target = Math.round(num('cmTarget'));
    if (isNaN(target)) target = 36;
    var error = document.getElementById('cmError');
    var bad = isNaN(balance) || isNaN(apr) || isNaN(pct) || isNaN(floor) || balance <= 0 || balance > 1e7 || apr < 0 || apr > 100 ||
              pct < 0 || pct > 100 || floor < 1 || (!isNaN(fixed) && fixed < 0) || target < 1 || target > 360;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a balance above $0, an APR from 0 to 100%, a minimum percentage from 0 to 100%, a dollar floor of at least $1 and a payoff goal of 1 to 360 months.';
      clearResults();
      return;
    }
    apr = apr / 100;
    var s = simulateMinimum(balance, apr, method, pct / 100, floor);
    set('cmFirst', money.format(s.first));
    if (!s.paidOff) {
      error.hidden = false;
      error.textContent = 'With these settings the minimum payment does not keep up with the interest, so paying only the minimum never clears the balance. Raise the percentage or the floor.';
      ['cmTime', 'cmInterest', 'cmTotal'].forEach(function (id) { set(id, '–'); });
      set('cmTimeNote', '');
    } else {
      set('cmTime', duration(s.months));
      set('cmTimeNote', s.months + (s.months === 1 ? ' payment' : ' payments') + ', each smaller than the last.');
      set('cmInterest', money.format(s.interest));
      set('cmTotal', money.format(s.paid));
    }

    var compare = clearBody('cmCompare');
    addRow(compare, ['Minimum payments only', money.format(s.first) + ' falling',
      s.paidOff ? duration(s.months) : 'Never', s.paidOff ? money.format(s.interest) : '–']);
    var fixedPay = !isNaN(fixed) && fixed > 0 ? fixed : s.first;
    var f = simulateFixed(balance, apr, fixedPay);
    addRow(compare, [isNaN(fixed) || fixed <= 0 ? 'Keep paying the first minimum' : 'Your fixed payment', money.format(fixedPay),
      f.paidOff ? duration(f.months) : 'Never', f.paidOff ? money.format(f.interest) : '–']);
    var goalPay = levelPayment(balance, apr, target);
    var g = simulateFixed(balance, apr, goalPay);
    addRow(compare, ['Pay off in ' + duration(target), money.format(goalPay), duration(g.months), money.format(g.interest)]);
    if (s.paidOff && f.paidOff && f.interest < s.interest) {
      set('cmSavings', 'Paying a fixed ' + money.format(fixedPay) + ' instead of the falling minimum saves ' +
        money.format(s.interest - f.interest) + ' in interest and finishes ' + duration(s.months - f.months) + ' sooner.');
    } else {
      set('cmSavings', '');
    }

    var body = clearBody('cmSchedule');
    s.years.forEach(function (y) {
      addRow(body, [String(y.year), money.format(y.startMin), money.format(y.paid), money.format(y.interest), money.format(y.balance)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cmForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
